import { invoiceDiscountCents } from './invoice-discount.js';
import { invoiceHeader } from './invoice-format.js';
import { lineAmountCents } from './invoice-lines.js';
import { invoiceTaxCents } from './invoice-tax.js';
import { validateInvoiceInput } from './invoice-validation.js';

export function createInvoice(input) {
  validateInvoiceInput(input);
  const lines = input.items.map((item) => ({ ...item, lineCents: lineAmountCents(item) }));
  const subtotalCents = lines.reduce((sum, line) => sum + line.lineCents, 0);
  const discountCents = invoiceDiscountCents(subtotalCents, input.discountBasisPoints ?? 0);
  const taxCents = invoiceTaxCents(subtotalCents - discountCents, input.taxBasisPoints ?? 0);
  return {
    ...invoiceHeader(input),
    lines,
    subtotalCents,
    discountCents,
    taxCents,
    totalCents: subtotalCents - discountCents + taxCents,
  };
}
EOF
